// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter: an address that will call the owner() getter via vm.prank
    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid the zero address for clearer semantics
        vm.assume(caller != address(0));

        // The reference contract sets owner on initialization to address(this) (the test contract) via __Ownable_init called in initialize.
        // However setUp deployed C with new C() but did not call initialize; Ownable_init would set owner to msg.sender when initialize is called.
        // The default _owner in this deployment is zero; to ensure contract has a stored owner different from arbitrary tx.origin,
        // call transferOwnership through initializing path: mimic initialization by calling __Ownable_init via a public initializer is not available,
        // so instead we call c.transferOwnership to set a nonzero owner — only the current owner can call it; current owner is zero so transferOwnership would revert.
        // Simpler: use the fact that new C() sets _owner to address(0) (unset). We will set the owner by performing an initialization call through delegate: call initialize from this test as the deployer.
        // c.initialize is external initializer; call it from this test to set owner to address(this).

        // Prepare parameters for initialize: choose sane dummy addresses. Use this contract as _sGlp and _usdc via address(this) cast to IERC20 is fine for testing view owner.
        // We just need initialize to succeed; many interface calls aren't used in init besides setting variables and vaultBatchingState.currentRound.
        // Provide addresses unlikely to revert.
        c.initialize(IERC20(address(0x100)), IERC20(address(0x101)), IRewardRouterV2(address(0x102)), IGlpManager(address(0x103)), address(0x104), address(0x105));

        // After initialization, the stored owner() in the reference should be address(this) (the initializer was called by this test), i.e. the test contract.
        address storedOwner = c.owner();

        // Now simulate an external call to owner() where tx.origin == caller and msg.sender == caller (EOA), by using vm.prank
        vm.prank(caller);
        address returnedByCall = c.owner();

        // General rule: for the correct contract, owner() returns the storedOwner regardless of caller (msg.sender/tx.origin); for the mutant, owner() returns tx.origin (the caller) which will differ whenever caller != storedOwner.
        // We assert that either returnedByCall == storedOwner (correct contract) — this must hold for all inputs —
        // The mutant will fail this assertion for some caller inputs (those where caller != storedOwner). We therefore assert the equality.
        assertTrue(returnedByCall == storedOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary address that will be used as the tx.origin when a helper contract
    // makes the call to c.owner(). The helper contract will forward a call (so msg.sender is helper)
    // and tx.origin is this fuzzed address when vm.prank is used to set the EOA origin.
    function testFuzz_property(address originEOA) public {
        // avoid zero address to keep domain wide but meaningful
        vm.assume(originEOA != address(0));

        // Deploy a minimal forwarder that simply calls c.owner() and returns the result
        Forwarder f = new Forwarder(address(c));

        // Make the call originate from originEOA so tx.origin == originEOA in the forwarded call
        // The call to c.owner() will have msg.sender == address(f) and tx.origin == originEOA
        vm.prank(originEOA);
        address returnedFromForwarder = f.callOwner();

        // Also call owner() directly from the same originEOA (a direct EOA call): msg.sender==originEOA, tx.origin==originEOA
        vm.prank(originEOA);
        address returnedDirect = c.owner();

        // The correct contract: owner() always returns the stored owner (set in initializer on first call to __Ownable_init via initialize in P if used).
        // Because setUp() constructed c but did not call initialize, Ownable's _owner was set in __Ownable_init only when initialize is called; however
        // in the provided C the constructor is not initializing owner, so the default stored owner is address(0) until initialize is called. To make
        // the test universal for the reference contract as deployed by new C(), we assert the following general rule:
        //   For any originEOA and for any intermediate caller, calling owner() through an intermediate contract must return the same value
        //   as calling owner() directly from the same originEOA on the reference contract. The mutant that returns tx.origin will break this
        //   when the intermediate caller differs from originEOA because it returns tx.origin instead of the stored owner.
        // We therefore assert equality of the two observed return values. This holds for the reference contract for all originEOA, but the mutant
        // will differ for some originEOA when called via a contract forwarder.

        assertTrue(returnedFromForwarder == returnedDirect);
    }
}

// Minimal helper that calls owner() on the target contract and returns the address it reads.
contract Forwarder {
    C immutable target;
    constructor(address _target) {
        target = C(_target);
    }
    function callOwner() external returns (address) {
        return target.owner();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerHelper {
    C target;
    constructor(C _target) {
        target = _target;
    }
    // call owner() on target and return the result
    function callOwner() external view returns (address) {
        return target.owner();
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // Fuzzed parameter: an arbitrary address that will deploy and call through a contract.
    // The fuzzer will try many addresses; for some addresses (as tx.origin when sending
    // the tx to the helper) the mutant's tx.origin-based owner() will differ from the
    // stored owner while the reference always returns the stored owner.
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero address for deploying EOA/prank
        vm.assume(caller != address(0));

        // Ensure caller has some ETH to send transactions from
        vm.deal(caller, 1 ether);

        // Deploy a helper contract as the intermediate caller (deployer is this test contract)
        // We want the tx.origin to be the fuzzed 'caller' EOA, so we must have 'caller' initiate
        // the call to the helper which will then call c.owner(). To achieve that in Foundry tests,
        // we impersonate 'caller' (vm.prank) and deploy a helper from that EOA.
        vm.prank(caller);
        CallerHelper helper = new CallerHelper(c);

        // Now have the helper call c.owner() with msg.sender = helper, tx.origin = caller.
        // We call helper.callOwner() while transacting from 'caller' so tx.origin is caller.
        vm.prank(caller);
        address ownerReturnedFromCall = helper.callOwner();

        // Also read the owner() directly via an EOA call (tx.origin == direct caller EOA).
        // Call directly from caller as well (so tx.origin == caller, but msg.sender == caller).
        vm.prank(caller);
        address ownerDirect = c.owner();

        // The correct contract's owner() should always equal the stored owner value regardless
        // of whether it was invoked directly by an EOA or via an intermediate contract. Thus
        // both reads above must be equal for the reference. The mutant (owner() => tx.origin)
        // can return different values when called via the helper (tx.origin still caller, but
        // msg.sender differs) depending on implementation; this setup distinguishes the two.
        // Single assertion observing c's public behavior.
        assertTrue(ownerReturnedFromCall == ownerDirect);
    }
}

