// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerForwarder {
    C public target;
    constructor(C _target) {
        target = _target;
    }
    // forward a call to owner() using a plain external call
    function callOwner() external view returns (address) {
        return target.owner();
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // General rule: for any caller, c.owner() must return the stored owner address (the value set by initializer)
    // The mutant returns tx.origin instead, so invoking owner() via an intermediate contract can make the mutant
    // return a different address while the reference still returns the stored owner.
    function testFuzz_property(address callerEOA) public {
        // keep callerEOA as an EOA (non-zero)
        vm.assume(callerEOA != address(0));

        // initialize C as in normal usage: run initializer from this test contract (a legitimate deployer)
        // The initializer modifier in C expects non-contract deploy context for second branch; we can call initialize
        // directly as the deploying test (this contract) is an EOA for the initializer semantics in tests.
        // However setUp already deployed c with new C(), but initialize was not called. We must call initialize now.
        // Prepare dummy params for initialize: we can pass address(1) etc. The function expects IERC20 types and addresses.
        // Use vm.prank to make this test contract the msg.sender (already is), and call initialize.
        c.initialize(IERC20(address(1)), IERC20(address(2)), IRewardRouterV2(address(3)), IGlpManager(address(4)), address(5), address(this));

        // After initialization, owner should be this test contract
        address storedOwner = c.owner();
        // sanity: storedOwner must equal address(this)
        assertTrue(storedOwner == address(this));

        // Deploy a helper contract that will call c.owner() on behalf of an EOA caller
        // We want tx.origin to be the EOA (callerEOA) and msg.sender in c.owner() to be the forwarder contract.
        // Use vm.prank to make the following deploy originate from callerEOA so tx.origin==callerEOA inside the forwarder when it calls c.owner().
        vm.prank(callerEOA);
        CallerForwarder forwarder = new CallerForwarder(c);

        // Now have the forwarder call c.owner() in a context where tx.origin == callerEOA and msg.sender == forwarder
        address ownerFromForwarder = forwarder.callOwner();

        // The correct contract should always return the stored owner regardless of caller; assert that.
        // This assertion is TRUE for the reference implementation for all inputs; the mutant (which returns tx.origin)
        // would return callerEOA here, differing from storedOwner for many fuzzed callerEOA values, making the test fail.
        assertTrue(ownerFromForwarder == storedOwner);
    }
}

// Minimal interfaces used for initialize call types
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}
interface IRewardRouterV2 { }
interface IGlpManager { function vault() external view returns (address); }

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // General rule: calling owner() through any caller (EOA or contract) must always return the stored owner
    // (the initializer-set owner). The mutant returns tx.origin and thus can return a different address when
    // invoked through an intermediate contract. We fuzz the caller EOA and ensure that calling owner() via a
    // deployed helper contract still returns the stored owner for the reference implementation.
    function testFuzz_property(address caller) public {
        // admissible domain: ignore zero address for caller to keep EOA meaningful
        vm.assume(caller != address(0));

        // initialize c with some parameters. many parameters are contract interfaces; we can pass arbitrary
        // addresses cast to the expected types. Use the caller as keeper to vary stored owner via msg.sender during
        // __Ownable_init (which sets owner to initializer's msg.sender). We will perform the initialize under a
        // prank from caller so the stored owner becomes caller.
        vm.prank(caller);
        c.initialize(
            IERC20(address(1)),
            IERC20(address(2)),
            IRewardRouterV2(address(3)),
            IGlpManager(address(4)),
            address(5),
            address(6)
        );

        // Deploy a helper contract that will call c.owner() and return what it sees. We will call the helper
        // from the same EOA 'caller' so that tx.origin == caller; the helper's call will have msg.sender == helper.
        Helper h = new Helper(c);

        // call helper.ownerView() as EOA 'caller' so tx.origin == caller. For the correct contract, owner() should
        // return the stored owner (which we set to caller). For the mutant, owner() would return tx.origin (caller)
        // as well in this exact case — so to expose difference we must call helper from a different EOA than the one
        // that initialized c. Therefore also test calling helper from a different EOA 'other'. The property we assert
        // is: owner() as observed when called directly by the owner EOA equals owner() as observed when called via
        // the helper contract (i.e., caller-invariant). The mutant can break this when the initializer (stored owner)
        // differs from tx.origin for the helper-call scenario.

        // compute direct owner observed by an EOA call (simulate direct call by caller)
        vm.prank(caller);
        address directOwner = c.owner();

        // pick a different EOA to act as tx.origin for the helper call; fuzzing gives us 'caller', we derive 'other'
        // as a simple transform — ensure it's different and nonzero
        address other = address(uint160(uint256(keccak256(abi.encodePacked(caller, block.timestamp)))));
        if (other == address(0) || other == caller) {
            other = address(0x123);
        }
        vm.assume(other != caller);

        // call helper.ownerView() from 'other' so tx.origin == other and inside c.owner() msg.sender == helper
        vm.prank(other);
        address viaHelper = h.ownerView();

        // The invariant: the owner observed directly by the stored owner EOA (directOwner) must equal the owner
        // observed when calling through an intermediate contract (viaHelper). The reference implementation
        // satisfies this for all inputs; the mutant (returning tx.origin) can make viaHelper == other != directOwner.
        assertTrue(directOwner == viaHelper);
    }
}

contract Helper {
    C immutable c;
    constructor(C _c) {
        c = _c;
    }
    function ownerView() external returns (address) {
        return c.owner();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xABCD);

    function setUp() public {
        c = new C();
        // initialize contract as owner via initializer pattern: call initialize from owner
        vm.prank(owner);
        // supply constructor-like initialize params with harmless zero addresses where allowed
        c.initialize(
            IERC20(address(1)), // sGlp
            IERC20(address(2)), // usdc
            IRewardRouterV2(address(3)),
            IGlpManager(address(4)),
            address(5), // dnGmxJuniorVault
            address(6)  // keeper
        );
    }

    // fuzz newOwner; we need at least one param
    function testFuzz_property(address newOwner) public {
        // keep wide: allow any address
        // We need to call transferOwnership as the current owner
        vm.prank(owner);

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference contract reverts when attempting to transfer ownership to zero address
        // so for newOwner == address(0) the call must fail (ok == false). The mutant removed the check and
        // will succeed (ok == true) for that input. We assert the property that for this fuzzed input,
        // the call fails iff newOwner == address(0).
        // Single assertion required: check that ok == (newOwner != address(0))
        assertTrue(ok == (newOwner != address(0)));
    }
}

