pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerAddr = address(0xABCD);

    function setUp() public { c = new C(); }

    // fuzz the newOwner address; when it's zero address the correct contract should revert,
    // the mutant (which allows zero) will not revert — so this distinguishes them.
    function testFuzz_property(address newOwner) public {
        // ensure caller is the contract owner (the deployer of C is this test contract)
        // but C uses OwnableUpgradeable initializer which sets owner to _msgSender() only when initialized;
        // however setUp created C via new C() without calling initialize, but OwnableUpgradeable's storage
        // _owner is private and initialized in __Ownable_init which is not invoked — in the given reference
        // C.__GMXBatchingManager_init sets owner via __Ownable_init called in initialize(). To ensure
        // the contract's owner is this test, we call initialize as owner. The initialize function is external
        // and protected by Initializable; calling it here is appropriate in tests.

        // Call initialize with dummy addresses; we need to provide suitable contracts for interfaces but
        // passing arbitrary addresses is fine because initialize will call glpManager.vault() — that would
        // revert if glpManager is a non-contract. To avoid calls during initialization to external contracts,
        // we pass addresses of minimal helpers that provide required view methods. We deploy minimal stubs.
        VmAddressHelpers helpers = new VmAddressHelpers();
        // Deploy dummy contracts to satisfy interfaces
        DummyERC20 sGlp = new DummyERC20();
        DummyERC20 usdc = new DummyERC20();
        DummyGlpManager glpManager = new DummyGlpManager(address(0xBEEF));
        DummyRewardRouterV2 rewardRouter = new DummyRewardRouterV2();
        DummyJuniorVault junior = new DummyJuniorVault();

        // initialize as this test contract (msg.sender of this call)
        c.initialize(IERC20(address(sGlp)), IERC20(address(usdc)), IRewardRouterV2(address(rewardRouter)), IGlpManager(address(glpManager)), address(junior), ownerAddr);

        // Ensure the test uses the ownerAddr to call transferOwnership
        vm.prank(ownerAddr);

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: when newOwner == address(0), the reference contract MUST revert (ok==false).
        // This distinguishes the mutant which removed the non-zero check and would set owner to zero (ok==true).
        if (newOwner == address(0)) {
            assertTrue(!ok);
        } else {
            // for non-zero addresses the call should succeed on the reference
            assertTrue(ok);
        }
    }
}

// Minimal helper stubs to satisfy external interface calls during initialize and later (no-op implementations)
interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
}
interface IGlpManager { function vault() external view returns (address); }
interface IRewardRouterV2 { function mintAndStakeGlp(address token, uint256 amount, uint256 minUsdg, uint256 minGlp) external returns (uint256); }

