pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: caller (who will be the owner) and newOwner candidate
    function testFuzz_property(address caller, address newOwnerCandidate) public {
        // keep addresses in wide admissible domain but avoid zero address for caller
        vm.assume(caller != address(0));

        // Make `caller` the owner by calling initializer path: the contract's initialize uses initializer modifier
        // but setUp deployed with constructor; Ownable initializer sets owner to msg.sender when called.
        // We can call __Ownable_init by invoking initialize and providing required args; however initialize requires parameters
        // Instead, use transferOwnership only allowed to owner. The deployed contract currently has owner == address(this) (the test contract deployer),
        // so we need to make `caller` be the owner. Use transferOwnership from current owner (this test) to set owner = caller.

        // current owner is address(this) (the test contract) because setUp deployed c via new C() in this test contract.
        bool ok;
        try c.transferOwnership(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // require that setting owner to caller succeeded in the reference; if it failed then we cannot proceed meaningfully
        // but to keep property universal, assume step succeeded
        vm.assume(ok);

        // now act as caller (the current owner) and attempt to transfer ownership to fuzzed newOwnerCandidate
        vm.startPrank(caller);
        bool callOk;
        try c.transferOwnership(newOwnerCandidate) {
            callOk = true;
        } catch {
            callOk = false;
        }
        vm.stopPrank();

        // Single assertion: after the call by the owner, owner() == newOwnerCandidate must hold (reference satisfies for all inputs).
        // The mutant that requires newOwner == _owner will cause calls where newOwnerCandidate != caller to revert/leave owner unchanged,
        // so this assertion will fail for some fuzz inputs on the mutant.
        assertTrue(c.owner() == newOwnerCandidate);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // fuzzed newOwner; property: when the caller is the current owner, reference allows changing owner to any address
    function testFuzz_property(address newOwner) public {
        // keep input wide but avoid zero-address since some semantics might disallow zero as sensible new owner in other contexts
        // However original Ownable.transferOwnership requires newOwner != address(0), so to keep admissible domain we must avoid zero
        vm.assume(newOwner != address(0));

        address currentOwner = c.owner();

        // ensure the test caller is the current owner
        // In the reference contract initialize wasn't called so owner is address(0) until __Ownable_init is invoked in initialize.
        // But per instructions we must use new C() verbatim. To make the caller the owner we need to call __Ownable_init via initialize.
        // The initialize function requires many args; supply minimal dummy contracts/addresses.
        // Deploy minimal mocks for interfaces used in initialize
        MockERC20 sGlp = new MockERC20();
        MockERC20 usdc = new MockERC20();
