    function setUp() public {
        c = new C();
    }

    // Fuzz parameters: the new owner candidate, and a boolean that if true will renounce ownership first
    function testFuzz_property(address newOwner, bool doRenounce) public {
        // admissible domain: newOwner may be any address (including zero)
        // We need to ensure there is a current owner who calls transferOwnership.
        // After construction, the contract's owner is the deployer (address(this) in setUp()).

        // If doRenounce is true, we will renounce ownership first (so owner() becomes address(0)).
        // Otherwise owner() stays as address(this).

        // Prepare caller: the current owner is address(this) (the test contract), so we will perform calls directly.

        if (doRenounce) {
            // renounce ownership from current owner
            c.renounceOwnership();
        }

        // Attempt transferOwnership from the current caller (address(this)) to newOwner.
        // We capture whether the call succeeded using try/catch, as required.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule (that the reference satisfies for all inputs):
        // If msg.sender equals the contract's current owner, transferOwnership(newOwner) should succeed and set owner() == newOwner.
        // In our setup, msg.sender is address(this). After setUp(), address(this) is the owner. After renounceOwnership(), owner()==address(0)
        // For the reference implementation: when msg.sender == owner() the call succeeds and owner() becomes newOwner (even if newOwner==address(0)).
        // The mutant adds an extra requirement owner() != address(0) which causes the transfer to revert when owner()==address(0).

        // We now assert the single universal property: if the call succeeded (ok==true) then owner() must equal newOwner.
        // This is a property the reference always satisfies; the mutant will produce some input (doRenounce==true)
        // where the call should have succeeded on the reference but mutant reverts (ok==false), thus the assertion
        // will fail on the mutant for that input because reference would have ok==true and owner()==newOwner.

        // However we must ensure this assertion is a universal property that holds on the reference for ALL admissible inputs.
        // On the reference, when msg.sender == owner(), transferOwnership will not revert and will set owner() to newOwner.
        // Our test invokes transferOwnership from the current owner (address(this)), so on the reference ok is always true and owner()==newOwner.

        // Single assertion reading c's public state as required:
        assertTrue(!ok || c.owner() == newOwner);
    }
}

