pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: paused() should reflect the internal _paused flag. We cannot read _paused directly,
    // but we can observe behavior that flips _paused: calling pauseDeposit (onlyKeeper) and unpauseDeposit (onlyKeeper)
    // flip the paused state via inherited _pause/_unpause which set _paused. The fuzzer supplies keeper address.
    // We will initialize keeper by calling setKeeper from the owner (deployer), then exercise pause/unpause via vm.prank.

    // The test fuzzes an address candidate for keeper; for the reference contract, after setKeeper(k) and
    // calling pauseDeposit/unpauseDeposit from k, the returned paused() value must match the sequence of operations
    // (true after pauseDeposit, false after unpauseDeposit). The mutant that inverts paused() will return opposite
    // values and thus fail for those keeper choices where calls succeed.

    function testFuzz_property(address keeperCandidate) public {
        // Avoid zero address keeper since setKeeper requires non-zero
        vm.assume(keeperCandidate != address(0));

        // owner is this contract (deployer) because we used new C() in setUp
        // set the keeper to the fuzzed candidate
        c.setKeeper(keeperCandidate);

        // Now simulate calls from keeperCandidate to pauseDeposit and unpauseDeposit.
        // The functions require msg.sender == keeper, so vm.prank as keeperCandidate will succeed.

        // Step 1: ensure initially contract is not paused (initializer sets paused = false)
        bool initiallyPaused = c.paused();

        // Now call pauseDeposit as keeperCandidate
        vm.prank(keeperCandidate);
        c.pauseDeposit();

        bool afterPause = c.paused();

        // Now call unpauseDeposit as keeperCandidate
        vm.prank(keeperCandidate);
        c.unpauseDeposit();

        bool afterUnpause = c.paused();

        // The single assertion encodes the invariant: paused() must reflect the actual pause flag transitions
        // For the reference: after pauseDeposit -> paused() must be true; after unpauseDeposit -> paused() must be false.
        // We assert that sequence holds. The mutant that inverts paused() will make this assertion fail for some keeperCandidate.
        assertTrue(!initiallyPaused && afterPause && !afterUnpause);
    }
}

