        // Keep domain wide but avoid zero address for roles to make operations valid
        vm.assume(actor != address(0));

        // The general property we will check:
        // In the reference, paused() returns the internal _paused flag. We can observe
        // the internal flag by calling _pause/_unpause indirectly via keeper/owner flows.
        // Since setUp constructed C (not initialized), we must initialize it to set owner/keeper.

        // Prepare helper contracts and tokens/interfaces are not available; instead,
        // we will initialize C with dummy addresses cast to expected types. That is allowed
        // because initialize only stores addresses and emits events and sets currentRound.

        // choose initialization parameters (use actor as owner/keeper to allow control)
        // Keep other addresses non-zero and arbitrary
        address dummyToken = address(0x100);
        address dummyUsdc = address(0x101);
        address dummyRewardRouter = address(0x102);
        address dummyGlpManager = address(0x103);
        address dummyJuniorVault = address(0x104);
        address keeper = actor;

        // initialize as actor (becomes owner via __Ownable_init calling _msgSender())
        vm.prank(actor);
        c.initialize(
