pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xABCD);
    address keeper = address(0xBEEF);

    function setUp() public {
        c = new C();
        // initialize with arbitrary valid params: we need to call initialize to set owner/keeper
        // Provide dummy token addresses and vault addresses as zero addresses are invalid for some flows,
        // but initialize only stores values and emits KeeperUpdated; we just need to set keeper.
        vm.prank(owner);
        // Call initialize with zero addresses for tokens/managers and keeper address; this will set owner via __Ownable_init being called from initializer
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0),
            keeper
        );
    }

    // General property test: after calling pause-related functions as allowed actors, paused() must reflect actual pause state
    // We fuzz a choice selector and verify the reported paused() matches the expected state after doing operations
    function testFuzz_property(uint8 actionSelector) public {
        // Keep selector wide but bounded to 0..3
        uint8 sel = actionSelector % 4;

        // Ensure owner is the owner for ownable actions
        vm.prank(owner);
        // transfer ownership to owner (owner already owner implicitly) to ensure owner identity aligns with `owner` variable
        // but transferOwnership requires new owner != zero; we skip changing owner and rely on initializer's __Ownable_init

        // Depending on sel we simulate sequences that change pause state via keeper-only and owner-only calls
        // 0: ensure initial state (contract initialized sets paused = false)
        // 1: keeper pauses -> paused should be true
        // 2: keeper pauses then keeper unpauses via executeBatchDeposit path that unpauses if cooldown passed; we will instead call unpauseDeposit via onlyKeeper to unpause
        // 3: test pause then unpause via keeper

        // For keeper-only calls we prune to use keeper address
        if (sel == 0) {
            // No action, just check initial paused state (should be false)
            bool reported;
            try c.paused() returns (bool r) { reported = r; } catch { reported = false; }
            // The invariant: initial reported paused() is false (contract initialized sets _paused = false)
            assertTrue(reported == false);
            return;
        }

        if (sel == 1) {
            // Pause via keeper
            vm.prank(keeper);
            c.pauseDeposit();
            bool reported;
            try c.paused() returns (bool r) { reported = r; } catch { reported = false; }
            // After pauseDeposit(), internal _pause() was called => _paused == true => paused() must return true
            assertTrue(reported == true);
            return;
        }

        if (sel == 2) {
            // Pause then unpause via keeper
            vm.prank(keeper);
            c.pauseDeposit();
            vm.prank(keeper);
            c.unpauseDeposit();
            bool reported;
            try c.paused() returns (bool r) { reported = r; } catch { reported = false; }
            // After unpauseDeposit(), internal _unpause() set _paused == false => paused() must return false
            assertTrue(reported == false);
            return;
        }

        if (sel == 3) {
            // Exercise owner-only setKeeper to a new keeper and ensure new keeper can pause
            address newKeeper = address(0xCAFE);
            vm.prank(owner);
            c.setKeeper(newKeeper);
            vm.prank(newKeeper);
            c.pauseDeposit();
            bool reported;
            try c.paused() returns (bool r) { reported = r; } catch { reported = false; }
            assertTrue(reported == true);
            return;
        }
    }
}

