contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the keeper and owner addresses (they may overlap) and a flag deciding which sequence to run
    function testFuzz_property(address keeper, address owner, bool doUnpauseAfterPause) public {
        // keep addresses non-zero to be admissible
        vm.assume(keeper != address(0));
        vm.assume(owner != address(0));

        // initialize contract via initialize(...) requires owner context; C.initialize is external and uses initializer
        // we must call initialize with appropriate dummy params; pass address(0) for token/router/manager as allowed
        vm.prank(owner);
        c.initialize(
            // IERC20 _sGlp,
            IERC20(address(0)),
            // IERC20 _usdc,
            IERC20(address(0)),
            // IRewardRouterV2 _rewardRouter,
            IRewardRouterV2(address(0)),
            // IGlpManager _glpManager,
            IGlpManager(address(0)),
            // address _dnGmxJuniorVault,
            address(0),
            // address _keeper
            keeper
        );

        // At init time the contract sets paused = false and currentRound = 1.
        // The property: after a keeper calls pauseDeposit (which invokes _pause) the public paused() must return true.
        // Conversely, if we then unpause via executeBatchDeposit flow which may call _unpause, paused() must return false.

        // First, the keeper should be able to pause
        vm.prank(keeper);
        c.pauseDeposit();

        // After pausing, paused() must return true on the reference contract
        bool observedAfterPause;
        try c.paused() returns (bool v) { observedAfterPause = v; } catch { observedAfterPause = false; }

        // If doUnpauseAfterPause is true we attempt to unpause via the keeper-controlled executeBatchDeposit path.
        if (doUnpauseAfterPause) {
            // executeBatchDeposit requires onlyKeeper and will attempt logic that is safe with zero balances; call it as keeper
            vm.prank(keeper);
            // may revert if cooldown not passed, so catch
            try c.executeBatchDeposit() { } catch { }

            // After attempting unpause, read paused() again
            bool observedAfterUnpause;
            try c.paused() returns (bool v2) { observedAfterUnpause = v2; } catch { observedAfterUnpause = false; }

            // Exactly one assertion: if unpause was attempted, the reference must not report still-paused if executeBatchDeposit succeeded in unpausing;
            // However executeBatchDeposit only unpauses when conditions met; to keep the property universal we assert the stronger universal relation:
            // After calling pauseDeposit(), the public paused() MUST be true. This holds for all inputs. The mutant inverts paused() and will make this assertion fail for some fuzzed inputs (keeper/owner combos).
            assertTrue(observedAfterPause, "paused() must be true after pauseDeposit");

            // note: we do not assert on observedAfterUnpause to keep single assertion requirement
        } else {
            // Single assertion required: paused() must be true after pauseDeposit()
            assertTrue(observedAfterPause, "paused() must be true after pauseDeposit");
        }
    }
}

