pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xABCD);
    address keeper = address(0xBEEF);

    function setUp() public {
        c = new C();
    }

    // Fuzz parameter: a boolean that chooses one of two sequences to exercise both pause and unpause flows.
    // The property: after executing a sequence of pause/unpause actions via the designated roles,
    // the public paused() view must equal the expected internal paused state. The mutant that inverts
    // paused() will cause this assertion to fail for some sequence (true/false) which the fuzzer will find.
    function testFuzz_property(bool seqChoice) public {
        // Make owner and keeper hold ETH so they can be used with vm.prank if needed (not strictly necessary here)
        vm.deal(owner, 1 ether);
        vm.deal(keeper, 1 ether);

        // initialize c with sensible params. Provide dummy addresses for token/router/manager/juniorVault
        // We keep them as contracts with no code by using address(...) casted to expected types.
        // The initialize function requires IERC20, IRewardRouterV2, IGlpManager, and addresses for vault and keeper.
        // Use owner as caller to become the contract owner via initializer path that uses _msgSender().
        vm.prank(owner);
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0),
            keeper
        );

        // At initialization the contract sets currentRound and leaves _paused = false via __Pausable_init.
        // So expected paused state initially is false.
        bool expected;

        if (seqChoice) {
            // Sequence A: keeper pauses, then keeper unpauses after updating lastUnpauseTimestamp to allow unpause path
            // First, ensure keeper can call pauseDeposit -> it calls _pause() which sets paused = true.
            vm.prank(keeper);
            c.pauseDeposit();
            expected = true; // after pauseDeposit, contract should be paused

            // Now try to unpause: unpauseDeposit requires onlyKeeper as well; call it via keeper
            vm.prank(keeper);
            c.unpauseDeposit();
            expected = false; // after unpauseDeposit, contract should be unpaused
        } else {
            // Sequence B: call pauseDeposit then call executeBatchDeposit which may call _unpause internally
            // make sure preconditions for executeBatchDeposit are satisfied minimally: set lastUnpauseTimestamp in past
            // executeBatchDeposit is onlyKeeper; call via keeper
            // First pause
            vm.prank(keeper);
            c.pauseDeposit();
            expected = true;

            // Warp time forward so any internal cooldown checks don't revert in buggy paths
            vm.warp(block.timestamp + 20 minutes);

            // executeBatchDeposit will attempt to unpause if paused and cooldown passed.
            vm.prank(keeper);
            c.executeBatchDeposit();
            expected = false; // after executeBatchDeposit, contract should be unpaused
        }

        // Observe the public paused() view. The correct contract returns the actual internal flag value.
        bool ok;
        try c.paused() returns (bool p) {
            ok = (p == expected);
        } catch {
            // If paused() reverts (it should not), treat as failure
            ok = false;
        }

        // Single assertion: the reference contract satisfies that paused() equals the expected internal state
        // for every input; the mutant that inverts paused() will make this assertion fail for some fuzzed seqChoice.
        assertTrue(ok);
    }
}

